test('invoiceTotals calculates discount and vat', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 },
      { sku: 'ICON-SET', qty: 2, discountPercent: 50 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const line1Total = 8500;
  const line1Discount = 850;
  const line1AfterDiscount = line1Total - line1Discount;
  const line1VAT = Math.round(line1AfterDiscount * 21 / 100);

  const line2Total = 1960;
  const line2Discount = 980;
  const line2AfterDiscount = line2Total - line2Discount;
  const line2VAT = Math.round(line2AfterDiscount * 21 / 100);

  assert.equal(totals.subtotal, line1Total + line2Total);
  assert.equal(totals.discount, line1Discount + line2Discount);
  assert.ok(totals.vat > 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

